    // Map a virtual-key code to a printable string (US layout).
    // Modifier flags are prefixed when active.
    static const char* VKeyToStr(UINT vk, bool shift, bool ctrl, bool alt) {
        static char buf[16];

        // Modifier prefixes
        std::string prefix;
        if (ctrl) prefix += "Ctrl+";
        if (alt)  prefix += "Alt+";

        auto emit = [&](const char* s) -> const char* {
            static std::string out;
            out = prefix + s;
            strncpy_s(out.c_str(), 0, "", 0); // no-op to silence unused warning
            strcpy_s(buf, sizeof(buf), out.c_str());
            return buf;
        };

        // Skip bare modifiers (handled by state tracking)
        if (vk == VK_SHIFT || vk == VK_CONTROL || vk == VK_MENU)
            return nullptr;

        // Letters / digits: use shift to pick case / symbol row
        if (vk >= 'A' && vk <= 'Z') {
            char c = static_cast<char>(vk);
            if (!shift) c = c + 32;               // lowercase
            snprintf(buf, sizeof(buf), "%s%c", prefix.c_str(), c);
            return buf;
        }
        if (vk >= '0' && vk <= '9') {
            char c = static_cast<char>(vk);
            if (shift) {
                static const char shifted[] = ")!@#$%^&*(";
                c = shifted[vk - '0'];
            }
            snprintf(buf, sizeof(buf), "%s%c", prefix.c_str(), c);
            return buf;
        }

        // Punctuation & special keys
        switch (vk) {
            case VK_SPACE:  return emit(" ");
            case VK_RETURN: return emit("\n");
            case VK_TAB:    return emit("\t");
            case VK_BACK:   return emit("[BACKSPACE]");
            case VK_ESCAPE: return emit("[ESC]");
            case VK_DELETE: return emit("[DEL]");
            case VK_CAPITAL: return emit("[CAPSLOCK]");
            case VK_OEM_1:   return emit(shift ? ":"  : ";");
            case VK_OEM_PLUS: return emit(shift ? "+" : "=");
            case VK_OEM_COMMA: return emit(shift ? "<" : ",");
            case VK_OEM_MINUS: return emit(shift ? "_" : "-");
            case VK_OEM_PERIOD: return emit(shift ? ">" : ".");
            case VK_OEM_2:   return emit(shift ? "?"  : "/");
            case VK_OEM_3:   return emit(shift ? "~"  : "`");
            case VK_OEM_4:   return emit(shift ? "{"  : "[");
            case VK_OEM_5:   return emit(shift ? "|"  : "\\");
            case VK_OEM_6:   return emit(shift ? "}"  : "]");
            case VK_OEM_7:   return emit(shift ? "\"" : "'");
